extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var game_autoload = get_node_or_null("/root/Game")
	if not check("autoload_exists", game_autoload != null, "L'Autoload Game deve essere presente"):
		return
	call_if_exists(game_autoload, "reset_session", [])
	set_prop_safe(game_autoload, "difficulty", 3)
	var basket_scene: Node = await instantiate_scene("res://basket.tscn")
	if not check("basket_instanced", basket_scene != null, "basket.tscn deve potersi istanziare"):
		return
	var calculated_speed = get_prop(basket_scene, "speed", 0.0)
	check("speed_adjusted", calculated_speed >= 419.0 and calculated_speed <= 421.0, "Con difficolta 3 la velocita deve essere 300 + 3*40 = 420.0, trovata: " + str(calculated_speed))
	call_if_exists(basket_scene, "_on_item_collected", [50])
	var cur_score = get_prop(game_autoload, "current_score", 0)
	check("score_saved", cur_score == 50, "Raccogliendo un oggetto Game.current_score deve aggiornarsi a 50")
	call_if_exists(basket_scene, "take_damage", [5])
	await wait_frames(2)
	check("game_over_reached", true, "La partita gestisce il danno letale senza errori")


func set_prop_safe(obj: Object, prop: String, val) -> void:
	if obj != null:
		obj.set(prop, val)
